import { URL } from 'node:url';

const DEFAULT_BASE_URL = 'https://demowebshop.tricentis.com';
const DEFAULT_ML_BASE_URL = 'https://www.mercadolibre.com.ar';

export interface EnvConfig {
  baseUrl: string;
  mlBaseUrl: string;
  testUserEmail?: string;
  testUserPassword?: string;
}

function parseHttpUrl(name: string, rawValue: string): string {
  const value = rawValue.trim();

  if (value.length === 0) {
    throw new Error(`${name} is empty. Provide an absolute http(s) URL.`);
  }

  let parsed: URL;

  try {
    parsed = new URL(value);
  } catch {
    throw new Error(`${name} is not a valid URL: "${value}".`);
  }

  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    throw new Error(`${name} must use http or https: "${value}".`);
  }

  return parsed.toString().replace(/\/$/, '');
}

export const env: EnvConfig = {
  baseUrl: parseHttpUrl(
    'BASE_URL',
    process.env.BASE_URL?.trim() || DEFAULT_BASE_URL,
  ),
  mlBaseUrl: parseHttpUrl(
    'ML_BASE_URL',
    process.env.ML_BASE_URL?.trim() || DEFAULT_ML_BASE_URL,
  ),
  testUserEmail: process.env.TEST_USER_EMAIL?.trim() || undefined,
  testUserPassword: process.env.TEST_USER_PASSWORD || undefined,
};

import type { Page } from '@playwright/test';

export abstract class BasePage {
  protected readonly page: Page;

  protected constructor(page: Page) {
    this.page = page;
  }

  async goto(path: string): Promise<void> {
    const normalizedPath = path.startsWith('/') ? path : `/${path}`;
    await this.page.goto(normalizedPath);
  }

  async getTitle(): Promise<string> {
    return this.page.title();
  }

  getUrl(): string {
    return this.page.url();
  }
}

import type { Locator, Page } from '@playwright/test';

export class HeaderComponent {
  readonly root: Locator;
  readonly registerLink: Locator;
  readonly loginLink: Locator;
  readonly cartLink: Locator;
  readonly cartQuantity: Locator;
  readonly logoutLink: Locator;
  readonly accountLink: Locator;

  constructor(page: Page) {
    this.root = page.locator('.header-links');
    this.registerLink = this.root.getByRole('link', { name: 'Register' });
    this.loginLink = this.root.getByRole('link', { name: 'Log in' });
    this.cartLink = this.root.getByRole('link', { name: /Shopping cart/ });
    this.cartQuantity = this.root.locator('.cart-qty');
    this.logoutLink = this.root.getByRole('link', { name: 'Log out' });
    this.accountLink = this.root.locator('a.account');
  }

  async openLogin(): Promise<void> {
    await this.loginLink.click();
  }

  async openRegister(): Promise<void> {
    await this.registerLink.click();
  }

  async openCart(): Promise<void> {
    await this.cartLink.click();
  }

  async getCartCount(): Promise<number> {
    const text = (await this.cartQuantity.innerText()).trim();
    const match = /^\((\d+)\)$/.exec(text);

    if (!match?.[1]) {
      throw new Error(`Unexpected cart counter format: "${text}".`);
    }

    return Number.parseInt(match[1], 10);
  }

  async getAuthenticatedEmail(): Promise<string> {
    const email = (await this.accountLink.innerText()).trim();

    if (email.length === 0) {
      throw new Error('No authenticated account email is visible in the header.');
    }

    return email;
  }

  async isLoggedIn(): Promise<boolean> {
    return this.logoutLink.isVisible();
  }
}

import type { Page } from '@playwright/test';
import { BasePage } from './base.page';

export class HomePage extends BasePage {
  constructor(page: Page) {
    super(page);
  }

  async open(): Promise<void> {
    await this.goto('/');
  }
}

import type { Locator, Page } from '@playwright/test';
import { BasePage } from './base.page';

export class LoginPage extends BasePage {
  readonly emailInput: Locator;
  readonly passwordInput: Locator;
  readonly loginButton: Locator;
  readonly errorSummary: Locator;

  constructor(page: Page) {
    super(page);
    this.emailInput = page.getByLabel('Email:');
    this.passwordInput = page.getByLabel('Password:');
    this.loginButton = page.getByRole('button', { name: 'Log in' });
    this.errorSummary = page.locator('.validation-summary-errors');
  }

  async open(): Promise<void> {
    await this.goto('/login');
  }

  async login(email: string, password: string): Promise<void> {
    await this.emailInput.fill(email);
    await this.passwordInput.fill(password);
    await this.loginButton.click();
  }

  async getErrorMessage(): Promise<string> {
    return (await this.errorSummary.innerText()).trim();
  }
}

import type { Locator, Page } from '@playwright/test';
import type { TestUser } from '../data/user.factory';
import { BasePage } from './base.page';

export class RegisterPage extends BasePage {
  readonly firstNameInput: Locator;
  readonly lastNameInput: Locator;
  readonly emailInput: Locator;
  readonly passwordInput: Locator;
  readonly confirmPasswordInput: Locator;
  readonly registerButton: Locator;
  readonly validationErrors: Locator;

  constructor(page: Page) {
    super(page);
    this.firstNameInput = page.getByLabel('First name:');
    this.lastNameInput = page.getByLabel('Last name:');
    this.emailInput = page.getByLabel('Email:');
    this.passwordInput = page.getByLabel('Password:', { exact: true });
    this.confirmPasswordInput = page.getByLabel('Confirm password:');
    this.registerButton = page.getByRole('button', { name: 'Register' });
    this.validationErrors = page.locator('.field-validation-error');
  }

  async open(): Promise<void> {
    await this.goto('/register');
  }

  async register(user: TestUser): Promise<void> {
    await this.firstNameInput.fill(user.firstName);
    await this.lastNameInput.fill(user.lastName);
    await this.emailInput.fill(user.email);
    await this.passwordInput.fill(user.password);
    await this.confirmPasswordInput.fill(user.password);
    await this.registerButton.click();
  }

  async getValidationMessages(): Promise<string[]> {
    const messages = await this.validationErrors.allInnerTexts();
    return messages.map((message) => message.trim());
  }
}

import type { Locator, Page } from '@playwright/test';
import { BasePage } from './base.page';

export class CartPage extends BasePage {
  readonly updateCartButton: Locator;
  readonly emptyMessage: Locator;

  constructor(page: Page) {
    super(page);
    this.updateCartButton = page.getByRole('button', { name: 'Update shopping cart' });
    this.emptyMessage = page.getByText('Your Shopping Cart is empty!');
  }

  async open(): Promise<void> {
    await this.goto('/cart');
  }

  getProductRow(productName: string): Locator {
    return this.page.locator('tr.cart-item-row').filter({ hasText: productName });
  }

  async updateQuantity(productName: string, qty: number): Promise<void> {
    const row = this.getProductRow(productName);
    await row.locator('input.qty-input').fill(String(qty));
    await this.updateCartButton.click();
  }

  async removeProduct(productName: string): Promise<void> {
    const row = this.getProductRow(productName);
    await row.getByRole('checkbox').check();
    await this.updateCartButton.click();
  }

  async getSubTotal(): Promise<string> {
    const row = this.page.locator('.cart-total tr').filter({ hasText: 'Sub-Total:' });
    return this.getSummaryValue(row);
  }

  async getTotal(): Promise<string> {
    const row = this.page
      .locator('.cart-total tr')
      .filter({ has: this.page.locator('.order-total') });
    return this.getSummaryValue(row);
  }

  async getEmptyMessage(): Promise<string> {
    return (await this.emptyMessage.innerText()).trim();
  }

  async isEmpty(): Promise<boolean> {
    return this.emptyMessage.isVisible();
  }

  private async getSummaryValue(row: Locator): Promise<string> {
    const value = await row.locator('.cart-total-right').innerText();
    return value.trim();
  }
}

import { randomBytes } from 'node:crypto';

export function randomString(length: number): string {
  if (!Number.isInteger(length) || length < 1) {
    throw new Error('randomString length must be a positive integer.');
  }

  return randomBytes(Math.ceil(length / 2)).toString('hex').slice(0, length);
}

