import type { APIRequestContext, APIResponse } from '@playwright/test';

export type ApiGetOptions = NonNullable<Parameters<APIRequestContext['get']>[1]>;
export type ApiPostOptions = NonNullable<Parameters<APIRequestContext['post']>[1]>;

export class ApiClient {
  protected readonly request: APIRequestContext;
  protected readonly baseUrl: string;

  constructor(request: APIRequestContext, baseUrl: string) {
    this.request = request;
    this.baseUrl = baseUrl.replace(/\/$/, '');
  }

  async get(path: string, options?: ApiGetOptions): Promise<APIResponse> {
    return this.request.get(this.buildUrl(path), options);
  }

  async post(path: string, options?: ApiPostOptions): Promise<APIResponse> {
    return this.request.post(this.buildUrl(path), options);
  }

  private buildUrl(path: string): string {
    return `${this.baseUrl}/${path.replace(/^\//, '')}`;
  }
}

import type { APIResponse } from '@playwright/test';
import { ApiClient } from './api-client';

export interface DepartmentCategory {
  name: string;
  id?: string;
  permalink?: string;
  children_categories?: DepartmentCategory[];
}

export interface Department {
  name: string;
  categories: DepartmentCategory[];
}

export interface DepartmentsResponse {
  departments: Department[];
}

export class MercadoLibreClient extends ApiClient {
  async getDepartments(): Promise<APIResponse> {
    return this.get('/menu/departments', {
      headers: {
        Accept: 'application/json',
      },
    });
  }
}

import type { APIResponse } from '@playwright/test';
import { ApiClient } from './api-client';

export interface AddToCartResponse {
  success: boolean;
  message: string;
  updatetopcartsectionhtml: string;
  updateflyoutcartsectionhtml: string;
}

export class ShopClient extends ApiClient {
  async addProductToCart(productId = 31, quantity = 1): Promise<APIResponse> {
    return this.post(`/addproducttocart/details/${productId}/${quantity}`, {
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
        'X-Requested-With': 'XMLHttpRequest',
        Referer: `${this.baseUrl}/141-inch-laptop`,
        Accept: '*/*',
      },
      form: {
        [`addtocart_${productId}.EnteredQuantity`]: String(quantity),
      },
    });
  }
}

import { expect, test } from '@playwright/test';
import {
  MercadoLibreClient,
  type DepartmentsResponse,
} from '../../src/api/mercadolibre.client';
import { env } from '../../src/config/env';

test('[API-ML-01] GET /menu/departments returns departments with name and categories', async ({
  request,
}) => {
  const client = new MercadoLibreClient(request, env.mlBaseUrl);
  const response = await client.getDepartments();

  expect(response.status()).toBe(200);
  expect(response.headers()['content-type']).toContain('application/json');

  const body = (await response.json()) as DepartmentsResponse;

  expect(Array.isArray(body.departments)).toBe(true);
  expect(body.departments.length).toBeGreaterThan(0);

  for (const department of body.departments) {
    expect(typeof department.name).toBe('string');
    expect(department.name.trim().length).toBeGreaterThan(0);
    expect(Array.isArray(department.categories)).toBe(true);

    for (const category of department.categories) {
      expect(typeof category.name).toBe('string');
      expect(category.name.trim().length).toBeGreaterThan(0);
    }
  }
});

import { expect, test } from '@playwright/test';
import { ShopClient, type AddToCartResponse } from '../../src/api/shop.client';
import { env } from '../../src/config/env';
import { stripHtml } from '../../src/utils/html';

test('[API-SHOP-01] POST addproducttocart returns success and cart confirmation', async ({
  request,
}) => {
  const client = new ShopClient(request, env.baseUrl);
  const response = await client.addProductToCart();

  expect(response.status()).toBe(200);
  expect(response.headers()['content-type']).toContain('application/json');

  const body = (await response.json()) as AddToCartResponse;

  expect(body.success).toBe(true);
  expect(stripHtml(body.message)).toContain(
    'The product has been added to your shopping cart',
  );
  expect(body.updatetopcartsectionhtml).toContain('(1)');

  const flyout = stripHtml(body.updateflyoutcartsectionhtml);
  expect(flyout).toContain('14.1-inch Laptop');
  expect(flyout).toContain('Quantity: 1');
});

